function clean(v){
    return String(v||"").replace(/\s+/g," " ).replace(/^\s+|\s+$/g,"");
}
function decode(v){
    return String(v||"")
        .replace(/&nbsp;/gi," ")
        .replace(/&amp;/gi,"&")
        .replace(/&lt;/gi,"<")
        .replace(/&gt;/gi,">")
        .replace(/&#39;/gi,"'")
        .replace(/&quot;/gi,'"')
        .replace(/&#x2F;/gi,"/")
        .replace(/&#(\d+);/g,function(_,n){try{return String.fromCharCode(Number(n));}catch(e){return _;}});
}
function text(v){
    return clean(decode(String(v||"").replace(/<script[\s\S]*?<\/script>/gi," " ).replace(/<style[\s\S]*?<\/style>/gi," " ).replace(/<[^>]+>/g," ")));
}
function attr(attrs,name){
    var re=new RegExp("(?:^|\\s)"+name+"\\s*=\\s*([\\\"'])([\\s\\S]*?)\\1","i");
    var m=String(attrs||"").match(re);
    return m?decode(m[2]):"";
}
function toBytes(v){
    var m=String(v||"").match(/([0-9.]+)\s*(TB|GB|MB|KB|B)/i);
    if(!m)return 0;
    var n=Number(m[1]||0),u=String(m[2]||"B").toUpperCase(),pow=0;
    if(u==="KB")pow=1;else if(u==="MB")pow=2;else if(u==="GB")pow=3;else if(u==="TB")pow=4;
    return Math.round(n*Math.pow(1024,pow));
}
function hashOf(v){
    var m=String(v||"").match(/btih:([A-Fa-f0-9]{40}|[A-Za-z2-7]{32})/i);
    if(!m)m=String(v||"").match(/(?:^|\/)([A-Fa-f0-9]{40})(?:$|[?#\/])/);
    if(!m)m=String(v||"").match(/([A-Fa-f0-9]{40})/);
    return m?String(m[1]).toUpperCase():"";
}
function magnet(h,t){
    var u="magnet:?xt=urn:btih:"+h;
    if(t)u+="&dn="+encodeURIComponent(t);
    return u;
}
function metaFromSegment(seg){
    var tx=text(seg),sm=tx.match(/(?:文件大小|文件尺寸|大小)\s*[:：]?\s*([0-9.]+\s*(?:TB|GB|MB|KB|B))/i);
    var fm=tx.match(/(?:文件数量|文件数)\s*[:：]?\s*(\d+)/i);
    var hm=tx.match(/(?:热度|下载次数)\s*[:：]?\s*(\d+)/i);
    var desc=[];
    if(sm)desc.push(sm[1]);
    if(fm)desc.push(fm[1]+"个文件");
    if(hm)desc.push("热度"+hm[1]);
    return {bytes:sm?toBytes(sm[1]):0,desc:desc.join(" · ")};
}
function add(out,seen,title,hash,segment){
    title=clean(title);
    hash=String(hash||"").toUpperCase();
    if(!title||!hash||seen[hash])return;
    seen[hash]=1;
    var md=metaFromSegment(segment||"");
    out.push({title:title,magnet:magnet(hash,title),bytes:md.bytes,seeders:-1,peers:-1,date:"",desc:md.desc});
}

var html=String(request(url,{headers:{"User-Agent":ua,"Accept":"text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8","Accept-Language":"zh-CN,zh;q=0.9,en;q=0.6","Referer":base+"/"},timeout:7000})||"");
