    if(!/(^|\s)title(\s|$)/i.test(cls))continue;
    var href=attr(attrs,"href"),h=hashOf(href);
    if(!h)continue;
    var title=attr(attrs,"title")||text(m[2]);
    var seg=html.substring(m.index,Math.min(html.length,m.index+5000));
    add(out,seen,title,h,seg);
    if(out.length>=60)break;
}
if(out.length)return out;

/* SCDht forks sometimes drop class=title; only accept 40-char detail links whose title/text contains the query. */
